# coding=utf-8

# 关键点：
#
# 1) 上面那段 JS 里，取数这段根本没被混淆，照抄即可：
#        const timestamp = Math.round(Date.now() / 1000);
#        let key = '';                          // 62 个字符里随机取 32 位
#        const token = document.getElementById('token').value;
#        const _md5 = md5('' + timestamp + token + key).toString();
#        document.cookie = '_asd2sdf99=' + _md5 + ...;
#        fetch('scraper-practice-c07', {method: 'POST',
#              body: JSON.stringify({key: key, token: token, timestamp: timestamp})})
#    签名顺序是 timestamp -> token -> key，别写反。
#
# 2) 这一关真正的坑在 GET：不带 User-Agent 裸 requests.get 会拿到 403 反爬页
#    （识别项目：User Agent 不符合浏览器特征），页面压根没解析到，token 静默
#    变成空串。而 token 为空时 md5(ts + '' + key) 和 md5('' + ts + key) 恰好
#    是同一个串，签名照样能过 —— 顺序写反也看不出来，最后答案还是对的。
#    两个错误互相抵消，只补其中一个反而立刻 403。所以 GET 必须带 UA，
#    取不到 token 就直接抛异常，别用空串兜底。
#
# 3) 服务端是真校验的，实测：
#        cookie 里的 md5 和 payload 三个字段对不上  ->  403 识别项目：请求参数异常
#        完全不带 cookie                            ->  403 同上
#        payload 为空                               ->  400 Invalid payload
#        timestamp 往前拨一小时                     ->  403 识别项目：Expired.
#    但 token 的内容本身不验（填 deadbeef 也返 200），服务端只要求 cookie 与
#    payload 自洽 + 时间戳新鲜。
#
# 4) 页面的 <tbody> 静态是空的，10 条数据全部来自这个 POST 接口。
#    表格里显示的 CPC 不是 cpc_usd 本身，而是 (cpc_usd ^ monthly_search_volume) / 100，
#    两个字段都是 int 且都小于 2^31，Python 的 ^ 和 JS 的 int32 语义一致。
#    合计 333.6，均值 33.36。
#
# 5) navigator.webdriver 为真时 JS 直接往表格里塞一段提示、连接口都不请求，
#    走 requests 天然绕开，这一关不需要 selenium。


import requests

from lxml import etree

import time

import json

import hashlib

import random

import string

import numpy as np

from pathlib import Path



base_url = 'https://spiderbuf.cn/challenge/scraper-practice-c07'

# 输出目录固定在脚本旁边，不受启动时工作目录影响；不存在就自动建
outdir = Path(__file__).resolve().parent / 'data' / 'c07'
outdir.mkdir(parents=True, exist_ok=True)



myheaders = {

    'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/91.0.4472.164 Safari/537.36'}


# JS 里生成 key 用的字符集和长度：大小写字母 + 数字里随机取 32 位
CHARACTERS = string.ascii_letters + string.digits

KEY_LENGTH = 32



def newSession():
    '''GET 一次页面拿 token。必须带 UA —— 裸 requests.get 会被判成爬虫返回 403 页面'''

    session = requests.Session()

    session.headers.update(myheaders)

    resp = session.get(base_url, timeout=15)

    resp.raise_for_status()

    return session, resp.text


def getToken(html):
    '''页面里的 <input type="hidden" name="token" id="token" value="...">，签名要用'''

    inputs = etree.HTML(html).xpath('//input[@id="token"]/@value')

    if not inputs:

        raise ValueError('没取到 token，多半是被反爬拦了，或者页面结构变了')

    return inputs[0]


def signPayload(token):
    '''复刻 JS 的取参和签名：md5(timestamp + token + key)，顺序不能换。
    key 每次现生成，写死也能过，但那样就不是这一关的解法了'''

    key = ''.join(random.choice(CHARACTERS) for _ in range(KEY_LENGTH))

    timestamp = round(time.time())          # JS 是 Math.round(Date.now() / 1000)

    md5_hash = hashlib.md5()

    md5_hash.update(f'{timestamp}{token}{key}'.encode('utf-8'))

    payload = {

        'key': key,

        'token': token,

        'timestamp': timestamp,

    }

    return payload, md5_hash.hexdigest()


def loadKeywords(file_name=''):
    '''打接口拿那 10 条关键词，CPC 按 JS 的算法还原'''

    session, html = newSession()

    token = getToken(html)

    payload, sign = signPayload(token)

    # JS 里是 document.cookie = '_asd2sdf99=' + _md5，服务端拿它和 payload 对账
    session.cookies.set('_asd2sdf99', sign)

    resp = session.post(base_url, json=payload, timeout=15)

    resp.raise_for_status()

    keywords = []

    for item in json.loads(resp.text):

        # 接口返回的 cpc_usd 是异或过的，表格里显示的才是下面这个值
        cpc = (item['cpc_usd'] ^ item['monthly_search_volume']) / 100

        keywords.append({

            'keyword': item['keyword'],

            'cpc_usd': cpc,

            'monthly_search_volume': item['monthly_search_volume'],

            'competition': item['competition'],

            'industry': item['industry'],

        })

    if file_name != '':

        with open(file_name, 'w', encoding='utf-8') as f:

            json.dump(keywords, f, ensure_ascii=False, indent=2)

    return keywords


def report(keywords):

    cpc_arr = [k['cpc_usd'] for k in keywords]

    print('关键词数量：', len(cpc_arr))

    print('CPC 总和：', round(sum(cpc_arr), 2))

    print('CPC 平均值：', round(np.average(cpc_arr), 2))


if __name__ == '__main__':

    keywords = loadKeywords(outdir / 'c07.json')

    for k in keywords:

        print(f"{k['cpc_usd']:8.2f}  {k['monthly_search_volume']:>7}  {k['keyword']}")

    report(keywords)